const input = $input.first().json;
const body = input.body || input;

const email = (body.email || '').trim().toLowerCase();
const password = body.password || '';

if (!email || !password) {
  return [{ json: { success: false, message: 'Email dan password wajib diisi' } }];
}

return [{ json: { email, password } }];

const crypto = require('crypto');
const user = $input.first().json;
const loginData = $node['Validate Input'].json;

if (!user.id) {
  return [{ json: { success: false, message: 'Email atau password salah' } }];
}

// Verify password (SHA-256 hash comparison)
const inputHash = crypto.createHash('sha256').update(loginData.password + (user.email)).digest('hex');

if (inputHash !== user.password_hash) {
  return [{ json: { success: false, message: 'Email atau password salah' } }];
}

// Generate session token
const sessionToken = crypto.randomBytes(48).toString('hex');

return [{ json: {
  success: true,
  authenticated: true,
  user_id: user.id,
  email: user.email,
  name: user.name,
  role: user.role,
  company: user.company_name || '',
  plan: user.plan_type || 'standard',
  api_key: user.api_key,
  token: sessionToken,
  client_id: user.client_id
}}];
